 1	import lockfile from 'proper-lockfile';
 2	import { join } from 'path';
 3	import { mkdir } from 'fs/promises';
 4	
 5	/**
 6	 * Lock configuration for the ledger directory.
 7	 * - 10 second stale timeout: locks older than this are considered stale
 8	 * - 50 retries with 200ms–1000ms backoff: retry window of 10–50s,
 9	 *   ensuring the window always covers the stale timeout duration
10	 */
11	const LOCK_OPTIONS = {
12	  stale: 10000, // 10 seconds
13	  retries: {
14	    retries: 50,
15	    minTimeout: 200,
16	    maxTimeout: 1000,
17	  },
18	};
19	
20	/**
21	 * Acquires a file lock on the project's centralized storage directory,
22	 * executes the callback, and releases the lock in a finally block.
23	 *
24	 * The lock file is created at {storageDir}/.lock
25	 *
26	 * @param storageDir - Absolute path to the project's storage directory
27	 * @param fn - Async callback to execute while holding the lock
28	 * @returns The return value of the callback
29	 * @throws Error if lock cannot be acquired after retries
30	 */
31	export async function withLock<T>(
32	  storageDir: string,
33	  fn: () => Promise<T>
34	): Promise<T> {
35	  const lockFilePath = join(storageDir, '.lock');
36	
37	  // Ensure the storage directory exists
38	  await mkdir(storageDir, { recursive: true });
39	
40	  // Acquire the lock
41	  let release: (() => Promise<void>) | null = null;
42	
43	  try {
44	    // proper-lockfile expects a file path, but we want to lock a directory.
45	    // We create a .lock file inside storageDir for this purpose.
46	    // Note: proper-lockfile creates a lockfile, so we don't need to pre-create it
47	    release = await lockfile.lock(storageDir, {
48	      ...LOCK_OPTIONS,
49	      lockfilePath: lockFilePath,
50	    });
51	
52	    // Execute the callback while holding the lock
53	    return await fn();
54	  } catch (error) {
55	    if ((error as NodeJS.ErrnoException).code === 'ELOCKED') {
56	      throw new Error(
57	        `Failed to acquire lock on ${storageDir} after ${LOCK_OPTIONS.retries.retries} retries. ` +
58	          `Another process may be holding the lock.`
59	      );
60	    }
61	    throw error;
62	  } finally {
63	    // Always release the lock, even if the callback throws
64	    if (release) {
65	      try {
66	        await release();
67	      } catch (error) {
68	        // Log but don't throw - we don't want to mask the original error
69	        console.error(
70	          `[file-lock] Warning: Failed to release lock on ${storageDir}:`,
71	          error
72	        );
73	      }
74	    }
75	  }
76	}

